def eval_capture(detail=False, items=()):
    source_path=ROOT/'data/evaltables-native.json'
    source=json.loads(source_path.read_text()) if source_path.exists() else {}
    image='evaltables-native-detail.png' if detail else 'evaltables-native.png'
    url=source.get('detail_url' if detail else 'url',source.get('url',''))
    rendered='<img src="/images/'+image+'" alt="Native Forge Evaluation Tables Preview showing saved workshop results">'
    if url: rendered='<a href="'+url+'">'+rendered+'</a>'
    positions=[(28.3, 62), (28.3, 84), (28.3, 27)] if detail else [(6, 39), (6, 77), (6, 53)]
    rendered+=''.join('<span class="eval-native-pin" style="left:'+str(x)+'%;top:'+str(y)+'%" aria-hidden="true">'+str(i)+'</span>' for i,(x,y) in enumerate(positions,1))
    notes=''.join('<p><b>'+str(i)+' · '+title+'</b><br>'+text+'</p>' for i,(title,text) in enumerate(items,1))
    return '<div class="eval-native"><div class="eval-native-image">'+rendered+'</div><div class="eval-native-notes">'+notes+'</div></div><p class="eval-native-caption">Recorded results in Forge · Evaluation Tables (Preview) · '+('<a href="'+url+'">Open this comparison ↗</a>' if url else 'Source link in the capture receipt')+'</p>'


def slide(key,title,body,notes='',cls=''):
    S.append(dict(key=key,title=title,body=body,notes=notes,cls=cls))
def code(text, focus=""): return '\n```python'+(' {'+focus+'}' if focus else '')+'\n'+text.strip()+'\n```\n'
def exercise(key,title,step,change,button,check,answer=None):
    slide(key,title,f'<div class="where">Notebook · {step}</div>\n\n<div class="task">{change}</div>\n\n<div class="done"><strong>Run:</strong> {button}<br><strong>Check:</strong> {check}</div>'+ (f'\n\n<a class="answer-link" href="#answer-{answer}">Worked answer →</a>' if answer else ''),f'Leave this slide up during the exercise. Ask someone to show the result and explain the change. Do not click a model-run control for them. The exact current control is: {button}.', 'exercise')
    S[-1]['exercise'] = dict(step=step, change=change, run=button, check=check)
