header='''---
theme: default
title: Please improve yourself · Pending, Inc.
author: Anish Shah
info: Build, instrument, evaluate and improve an agent in your own Forge project.
class: cover
aspectRatio: 16/9
canvasWidth: 1280
colorSchema: light
transition: fade
fonts:
  sans: IBM Plex Sans
  mono: IBM Plex Mono
  provider: none
mdc: true
highlighter: shiki
lineNumbers: false
drawings:
  enabled: false
exportFilename: pending-inc
---
'''
ids={s['key']:i+1 for i,s in enumerate(S)}
parts=[]
for i,s in enumerate(S):
    body=re.sub(r'(<table[^>]*>)(.*?)(</table>)',
        lambda m: m.group(0) if '<thead' in m.group(2) or '<tbody' in m.group(2)
        else m.group(1)+'<tbody>'+m.group(2)+'</tbody>'+m.group(3), s['body'], flags=re.S)
    if s['key']=='native-results':
        body=re.sub(r'<a href="([^"]+)" class="capture-frame".*?</a>',r'<a class="capture-link" href="\1"><CaptureDetail src="/images/visual-v030-pending-comparison.png" :x="80" :y="305" :width="1180" :height="380" label="Four saved W&B Table case rows, scores and execution evidence" /></a>',body)
    body=re.sub(r'(<div class="bottom-note"[^>]*>)(.*?)(</div>)',lambda m:m.group(1)+re.sub(r'`([^`]+)`',r'<code>\1</code>',m.group(2))+m.group(3),body)
    for key,n in ids.items():
        body=body.replace('](#'+key+')',f']({BASE}/{n})').replace('href="#'+key+'"',f'href="{BASE}/{n}"')
    if s['cls']=='answer': body=re.sub(r'\[([^]]*(?:Return|Continue)[^]]*)\]\(([^)]+)\)',r'<span class="source-link"><a href="\2">\1</a></span>',body)
    content=f'# {s["title"]}\n\n{body}\n\n<!--\n{s["notes"]}\n-->\n'
    if i: content=('---\n'+('class: '+s['cls']+'\n' if s['cls'] else '')+'---\n\n')+content
    parts.append(content)
(ROOT/'slides.md').write_text(header+'\n'.join(parts))
(ROOT/'notes/facilitator-notes.md').write_text('# Pending, Inc. presenter notes\n\nOne four-hour session, including breaks at 1:10–1:20 and 2:15–2:25.\n\n'+ '\n\n'.join(f'## {i+1}. {s["title"].replace("<br>"," ")}\n\n{s["timing"]["section"]} · {s["timing"]["start_minute"]}–{s["timing"]["start_minute"]+s["timing"]["duration_minutes"]} minutes\n\n{s["notes"]}' for i,s in enumerate(S))+'\n')
(ROOT/'notes/slide-map.json').write_text(json.dumps({'duration_minutes':240,'total_slides':len(S),'main_slides':ids['answer-tool']-1,'sections':[dict(anchor=key,title=title,start_minute=start,duration_minutes=duration) for key,title,start,duration,*_ in SECTIONS],'slides':[{'number':i+1,'key':s['key'],'title':s['title'],'kind':s['cls'] or 'explanation','notes':s['notes'],**{field:s[field] for field in ('concept','exercise','source','evidence','timing')},'answer': next((ids[key] for key in ids if key.startswith('answer-') and ('#'+key+'\"') in s['body']),None)} for i,s in enumerate(S)]},indent=2)+'\n')
print(f'Wrote {len(S)} slides')
